insert:
id: libraryIconSelect
width: 480
signal accepted()
signal rejected()
signal checkBoxClicked(int idx)
signal warningDialogClosed()
property string page_title: "Page Title"
property var properties
property bool all_icon_invisible: false
readonly property int flickableAreaMaxHeight: 612
property int firstPressedPositionY: -1
readonly property int visibleAnimationDuration: 100
readonly property int invisibleAnimationDuration: 0
property bool isMovingUp: false
property bool isMovingDown: false
function setState()
{
if (list.atYBeginning && (isMovingUp || list.movingVertically)) {
state = "TopEdgeOn"
} else if (list.atYBeginning && !isMovingUp && !list.movingVertically) {
state = "EdgeOff"
} else if (list.atYEnd && (isMovingDown || list.movingVertically)) {
state = "BottomEdgeOn"
} else if (list.atYEnd && !isMovingDown && !list.movingVertically) {
state = "EdgeOff"
} else {
state = ""

}
function onReleased()
{
isMovingUp = false
isMovingDown = false
firstPressedPositionY = -1
setState()
}
function pressedYPosition(posY)
{
firstPressedPositionY = posY
}
function movingYPosition(posY) {
if (firstPressedPositionY === -1) {
isMovingUp = false
isMovingDown = false
return
}
if ((firstPressedPositionY - posY) < 0) {
isMovingUp = true
isMovingDown = false
} else if ((firstPressedPositionY - posY) > 0) {
isMovingUp = false
isMovingDown = true
} else {
isMovingUp = false
isMovingDown = false
}
setState()
}
states: [
State {
name: "TopEdgeOn"
PropertyChanges { target: topImage; opacity: 1; }
PropertyChanges { target: bottomImage; opacity: 0; }
},
State {
name: "BottomEdgeOn"
PropertyChanges { target: topImage; opacity: 0; }
PropertyChanges { target: bottomImage; opacity: 1; }
},
State {
name: "EdgeOff"
PropertyChanges { target: topImage; opacity: 0; }
PropertyChanges { target: bottomImage; opacity: 0; }
},
State {
name: "None"
PropertyChanges { target: topImage; opacity: 0; }
PropertyChanges { target: bottomImage; opacity: 0; }
}
]
transitions: [
Transition {
to: "TopEdgeOn"
PropertyAnimation { target: topImage; property: "opacity"; duration: visibleAnimationDuration; }
PropertyAnimation { target: bottomImage; property: "opacity"; duration: invisibleAnimationDuration; }
},
Transition {
to: "BottomEdgeOn"
PropertyAnimation { target: topImage; property: "opacity"; duration: invisibleAnimationDuration; }
PropertyAnimation { target: bottomImage; property: "opacity"; duration: visibleAnimationDuration; }
},
Transition {
to: "EdgeOff"
PropertyAnimation { target: topImage; property: "opacity"; duration: visibleAnimationDuration; }
PropertyAnimation { target: bottomImage; property: "opacity"; duration: visibleAnimationDuration; }
},
Transition {
to: "None"
PropertyAnimation { target: topImage; property: "opacity"; duration: invisibleAnimationDuration; }
PropertyAnimation { target: bottomImage; property: "opacity"; duration: invisibleAnimationDuration; }
}
]
QtObject {
id: p
property int titleWidth: 480
property int titleHeight: 90
property int listHeight: 86
property int checkBoxHeight: 84
property int buttonMargin: 14
property int buttonBottom: 20
property int buttonHeight: 62
property int buttonWidth: 200
property int buttonCenterMargin: 12
property int textMargin: 20
property int scrollRightMargin:8
}
function openLibraryIconSelectWarningDialog(){
dialog.dialogOpen("kMid0017","", qsTr("020198"), 0)
}
DialogWrapper {
id: dialog
visible: false
dialog: "OkDialog"
onConfirmed: {
libraryIconSelect.warningDialogClosed()
}
}
Rectangle {
id: base
anchors.fill: parent
color: viewstyle.bgcolor.D1
}
Item {
id: titleArea
width: p.titleWidth
height: p.titleHeight
anchors { top: base.top; left: base.left}
SCmnLabel {
anchors { top: parent.top; bottom: parent.bottom; left: parent.left; leftMargin: p.textMargin; right: parent.right; }
font.pixelSize: viewstyle.textsize.L
font.weight: Font.Light
text: page_title
color: viewstyle.textcolor.L1
verticalAlignment: Text.AlignVCenter
horizontalAlignment: Text.AlignLeft
}
Image {
anchors { bottom: parent.bottom; left: parent.left }
source: "qrc:/assets/images/separator_main.png"
}
}
Item {
id: listArea
anchors { top: titleArea.bottom; left: parent.left; right: parent.right; bottom: buttonRow.top; bottomMargin: p.buttonMargin; }
ListView {
id: list
anchors.fill: parent
model: libraryIconSelect.properties
boundsBehavior: Flickable.StopAtBounds
delegate: listDelegate
clip: true
onAtYBeginningChanged: libraryIconSelect.setState()
onAtYEndChanged: libraryIconSelect.setState()
onMovingVerticallyChanged: libraryIconSelect.setState()
}
SCmnScrollIndicator {
id: scroll
flickable: list
anchors { top: list.top; bottom: list.bottom; right: list.right; rightMargin: p.scrollRightMargin; }
}
Component {
id: listDelegate
Item {
width: list.width
height: p.listHeight
SCmnCheckBoxWithSubject {
id: iconSelectList
anchors { top: parent.top; left: parent.left; right: parent.right; leftMargin: p.textMargin }
height: p.checkBoxHeight
checked: visibility
loadComponent: SCmnLabel {
wrapMode: Text.Wrap
text: PathLabels.label(icon_name_oneline,qsTr("020031"))
font.pixelSize: viewstyle.textsize.L
font.weight: Font.Light
color: viewstyle.textcolor.L1
verticalAlignment: Text.AlignVCenter
horizontalAlignment: Text.AlignLeft
}
onClicked: {
libraryIconSelect.checkBoxClicked(index)
}
onEdgeReleased: libraryIconSelect.onReleased()
onEdgeCanceled: libraryIconSelect.onReleased()
onPressedYPosition: libraryIconSelect.pressedYPosition(posY)
onMovedYPosition: libraryIconSelect.movingYPosition(posY)
}
Image {
id: listSeparator
anchors { bottom: parent.bottom; left: parent.left }
source: "qrc:/assets/images/separator_sub2.png"
}
}
}
}
Item {
id: buttonRow
height: p.buttonHeight
anchors { left: parent.left; right: parent.right; bottom: parent.bottom; bottomMargin: p.buttonBottom }
GeneralSimpleButton {
id: cancelButton
anchors { top: buttonRow.top; bottom: buttonRow.bottom; right: buttonRow.horizontalCenter; rightMargin: p.buttonCenterMargin}
minimum_width: p.buttonWidth
maximum_width: p.buttonWidth
text: qsTr("000001") + viewstyle.empty_string
text_size: viewstyle.textsize.S
onClicked: {
libraryIconSelect.rejected()
}
}
GeneralSimpleButton {
id: okButton
enable: !libraryIconSelect.all_icon_invisible
anchors { top: buttonRow.top; bottom: buttonRow.bottom; left: buttonRow.horizontalCenter; leftMargin: p.buttonCenterMargin}
minimum_width: p.buttonWidth
maximum_width: p.buttonWidth
text: qsTr("000000") + viewstyle.empty_string
text_size: viewstyle.textsize.S
onClicked: {
libraryIconSelect.accepted()
}
}
}
Image {
id: topImage
anchors { top: listArea.top; left: listArea.left; right: listArea.right; }
source: "qrc:/ic_list_full_end_mask_upper.png"
height: sourceSize.height
opacity: 0
}
Image {
id: bottomImage
anchors { bottom: listArea.bottom; left: listArea.left; right: listArea.right; }
source: "qrc:/ic_list_full_end_mask_lower.png"
height: sourceSize.height
opacity: 0
}
}
